  box-shadow: none;
}

.chips button.is-on, .mediums button.is-on, .ink-row button.is-on, .chips button[aria-checked='true'], .chips button[aria-pressed='true'] {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}

.bar-actions { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.mediums { display: flex; flex-wrap: wrap; gap: 0.35rem; }

.notice, .plan-note {
  margin: 0.6rem 0 0;
  padding: 0.4rem 0.6rem;
  border-left: 2px solid var(--cadmium);
  background: color-mix(in srgb, var(--cadmium) 6%, transparent);
  color: var(--graphite);
  font-size: 0.9rem;
}
.plan-note.is-live { border-left-color: var(--viridian); background: color-mix(in srgb, var(--viridian) 7%, transparent); }

/* Field sheet */
.sheet {
  position: absolute;
  z-index: 4;
  left: 0;
  right: 0;
  bottom: 0;
  max-height: min(74dvh, 40rem);
  overflow: auto;
  padding: 0.9rem 1.2rem 1.1rem 1rem;
  border-bottom: 0;
  animation: rise var(--ease);
}

.sheet-top, .sheet-actions {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  align-items: center;
}

.sheet-top { padding-bottom: 0.45rem; border-bottom: 1px dashed var(--rule); }

.sheet h2 {
  margin: 0 0 0.15rem;
  font-family: var(--display);
  font-size: 1.85rem;
  font-weight: 650;
  letter-spacing: -0.025em;
  line-height: 1.05;
}

.study-hero {
  display: grid;
  grid-template-columns: 6.4rem 1fr;
  gap: 0.75rem;
  align-items: end;
  margin-top: 0.7rem;
}
.study-hero .study-art { height: 4.6rem; }

.directions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.7rem;
  margin: 0.55rem 0 0;
  font-family: var(--mono);
  font-size: 0.8rem;
}
.directions a {
  color: var(--cobalt);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.sheet .field-label { margin-top: 1rem; }

.hint-inline {
  margin: 0.25rem 0 0.5rem;
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.4;
}

.values {
  list-style: none;
  padding: 0;
  margin: 0.35rem 0 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.35rem;
}

.value {
  min-height: 4.6rem;
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.3rem;
  padding: 0.4rem 0.45rem;
  font-size: 0.8rem;
  line-height: 1.25;
}
.value-step { font-family: var(--mono); font-size: 0.7rem; font-weight: 600; }
.value-1 { background: #f8f7f2; border: 1px solid var(--rule); }
.value-2 { background: #a7a59d; color: #141310; }
.value-3 { background: #2a2925; color: #f4f2ec; }

.swatches {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.35rem;
  margin-top: 0.35rem;
}

.swatch {
  min-height: 4.2rem;
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 0.1rem;
  padding: 0.4rem 0.45rem;
  border: 1px solid rgba(28, 25, 20, 0.22);
  font-size: 0.72rem;
}
.swatch .value-name { font-size: 0.9rem; font-weight: 650; }
.swatch span:not(.value-name) { font-family: var(--mono); }

.ink-row { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: 0.4rem; }

.motif {
  margin: 1.05rem 0 0.3rem;
  padding-top: 0.75rem;
  border-top: 1px dashed var(--rule);
  font-family: var(--display);
  font-size: 1.22rem;
  font-weight: 500;
  line-height: 1.2;
}
.subject, .leave { margin: 0.3rem 0 0; }
.leave { color: var(--viridian); font-style: italic; }

.sheet-actions { flex-wrap: wrap; margin-top: 1rem; }
.sheet-actions .primary, .sheet-actions .secondary { white-space: nowrap; }

.work { display: flex; align-items: center; gap: 0.65rem; margin-top: 0.8rem; }
.work p { margin: 0; color: var(--muted); font-family: var(--mono); font-size: 0.8rem; }

/* Library */
.visit-group { margin-top: 0.9rem; }
.visit-list { list-style: none; margin: 0.4rem 0 0; padding: 0; display: flex; flex-direction: column; gap: 0.3rem; }
.visit-list li { display: flex; align-items: center; gap: 0.35rem; }
.visit-list li > button:first-child { flex: 1; width: auto; }
.visit-list li > .text-button { width: auto; border-color: transparent; background: transparent; padding: 0.28rem 0.45rem; }
.visit-list button {
  width: 100%;
  display: flex;
  gap: 0.55rem;
  align-items: center;
  text-align: left;
  background: var(--card);
  border: 1px solid var(--rule-soft);
  border-radius: var(--radius);
  padding: 0.45rem 0.55rem;
  transition: border-color var(--ease), transform var(--ease), box-shadow var(--ease);
}
.visit-list li.is-studied > button:first-child { border-left: 3px solid var(--viridian); }
.visit-list strong, .suggest-row strong { display: block; font-family: var(--display); font-weight: 650; }
.visit-list small, .suggest-row small { color: var(--muted); font-size: 0.72rem; }
.pin-key { width: 0.7rem; height: 0.7rem; border-radius: 50%; flex: 0 0 auto; background: var(--cobalt); }
.pin-key.pin-water { background: #2f7f95; }
.pin-key.pin-park { background: #1f6b56; }
.pin-key.pin-viewpoint { background: #d4532b; }
.pin-key.pin-architecture { background: #5b4a3c; }
.pin-key.pin-hill { background: #7a7a3a; }
.google-button { min-height: 2.4rem; margin-top: 0.4rem; }

/* Map markers */
.here-pin {
  z-index: 3;
  width: 1.05rem;
  height: 1.05rem;
  border-radius: 50%;
  background: #4285f4;
  border: 3px solid #fff;
  box-shadow: 0 0 0 7px rgba(66, 133, 244, 0.3);
  pointer-events: none;
}

.here-label {
  position: absolute;
  left: 50%;
  top: calc(100% + 0.45rem);
  transform: translateX(-50%);
  white-space: nowrap;
  background: #1a73e8;
  color: #fff;
  font-family: var(--mono);
  font-size: 0.68rem;
  font-weight: 600;
  line-height: 1.2;
  padding: 0.2rem 0.45rem;
  border-radius: var(--radius);
  animation: here-say 4.2s ease forwards;
}

@keyframes here-say {
  0%, 60% { opacity: 1; }
  100% { opacity: 0; }
}

.place-flag {
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: none;
}
.place-flag::after {
  content: '';
  width: 1.5px;
  height: 8px;
  background: var(--ink);
}
.place-flag-art {
  width: 2.3rem;
  height: 2.3rem;
  border: 2px solid var(--ink);
  border-radius: var(--radius);
  overflow: hidden;
  background: #fff;
  box-shadow: var(--shadow);
}
.place-flag-art svg { width: 100%; height: 100%; display: block; }
.place-flag-name {
  max-width: 11rem;
  margin-top: 0.2rem;
  padding: 0.1rem 0.4rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 0.66rem;
  font-weight: 500;
  border-radius: var(--radius);
}

/* Explorer: a bottom sheet on phones and tablets, a side panel on desktop. */
.explorer, .gate {
  position: absolute;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  overflow: hidden;
  animation: rise var(--ease);
}

.gate {
  left: 0.5rem;
  right: 0.5rem;
  bottom: max(0.5rem, env(safe-area-inset-bottom));
  padding: 0.85rem 0.9rem 0.95rem;
  gap: 0.3rem;
}

.explorer {
  left: 0;
  right: 0;
  bottom: 0;
  height: 56dvh;
  padding: 0 0.75rem max(0.6rem, env(safe-area-inset-bottom));
  border-bottom: 0;
  transition: height 260ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.explorer[data-snap='peek'] { height: 13.5rem; }
.explorer[data-snap='half'] { height: min(56dvh, calc(100dvh - var(--bar-h, 7rem) - 12px)); }
.explorer[data-snap='full'] { height: calc(100dvh - var(--bar-h, 7rem) - 12px); }
.explorer.is-dragging { transition: none; }

.sheet-handle {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: calc(100% + 1.5rem);
  margin: 0 -0.75rem -0.2rem;
  height: 1.35rem;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: grab;
  touch-action: none;
}
.sheet-handle span {
  width: 2.6rem;
  height: 4px;
  border-radius: 2px;
  background: var(--rule);
  transition: background-color var(--ease), width var(--ease);
}
.sheet-handle:hover span, .explorer.is-dragging .sheet-handle span { background: var(--cobalt); width: 3.2rem; }
.explorer.is-dragging .sheet-handle { cursor: grabbing; }

.gate h2 {
  margin: 0.1rem 0 0.1rem;
  font-family: var(--display);
  font-size: 1.6rem;
  font-weight: 650;
  letter-spacing: -0.025em;
  line-height: 1.1;
}
.gate-copy, .explorer-note { margin: 0; color: var(--muted); font-size: 0.78rem; }
.gate .chips { margin-top: 0.45rem; }
.gate .primary { margin-top: 0.7rem; }

.explorer-nav, .explorer-row, .refine-panel, .explorer-note { flex-shrink: 0; }

.explorer-nav { display: flex; align-items: center; gap: 0.4rem; }
.explorer-nav .text-button { flex: 0 0 auto; }
.explorer-nav .text-button[aria-expanded='true'] { border-color: var(--cobalt); color: var(--cobalt); background: #fbfaf6; }

.back-button {
  width: 2.2rem;
  height: 2.2rem;
  flex: 0 0 auto;
  border: 1px solid var(--rule);
  background: color-mix(in srgb, #fbfaf6 70%, transparent);
  color: var(--ink);
  padding: 0;
}

.use-map { flex: 1; }

.refine-panel {
  display: grid;
  gap: 0.55rem;
  padding: 0.6rem;
  border: 1px dashed var(--rule);
  border-radius: var(--radius);
  background: color-mix(in srgb, #fbfaf6 55%, transparent);
}

.prompt { display: flex; flex-wrap: wrap; gap: 0.35rem; margin: 0; }
.prompt .field-label { flex: 1 0 100%; }

.explorer-row { display: flex; gap: 0.4rem; align-items: center; }

.chips { display: flex; flex-wrap: wrap; gap: 0.3rem; }
.chips button { flex: 0 0 auto; }

/* Results rows */
.rail {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  margin: 0 -0.75rem 0 0;
  padding: 0.1rem 0.85rem 0.3rem 0;
  scrollbar-width: none;
}
.rail::-webkit-scrollbar, .sheet::-webkit-scrollbar { display: none; }

.rail-content { display: flex; flex-direction: column; gap: 0.3rem; }

.preview {
  width: 100%;
  display: grid;
  grid-template-columns: 3.5rem 1fr;
  gap: 0.6rem;
  align-items: center;
  padding: 0.3rem 0.45rem 0.3rem 0.3rem;
  border: 1px solid var(--rule-soft);
  border-radius: var(--radius);
  background: var(--card);
  text-align: left;
  transition: transform var(--ease), border-color var(--ease), box-shadow var(--ease), background-color var(--ease);
}
.preview.is-hovered, .preview:focus-visible {
  border-color: var(--cobalt);
  background-color: #fbfaf6;
  box-shadow: 3px 3px 0 var(--rule-soft);
  transform: translate(-1px, -1px);
}
.preview:active { transform: translate(1px, 1px); box-shadow: none; }

.preview .study-art { height: 3.5rem; }
.preview-copy { min-width: 0; }
.preview h3 {
  margin: 0;
  font-family: var(--display);
  font-size: 1.02rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.preview p { margin: 0.15rem 0 0; color: var(--muted); font-size: 0.72rem; }
.preview .preview-best { color: var(--viridian); font-weight: 600; }
.preview .preview-best::before { content: '◆ '; font-size: 0.6rem; vertical-align: 0.05rem; }

.study-art {
  display: block;
  width: 100%;
  border-radius: 2px;
  border: 1px solid var(--rule-soft);
  object-fit: cover;
  background: #fbfaf6;
}

/* Loading rows: pencil hatching that moves. */
.preview.is-ghost { pointer-events: none; }
.preview.is-ghost .study-art {
  height: 3.5rem;
  background-image: repeating-linear-gradient(-45deg, var(--rule-soft) 0 1px, transparent 1px 6px);
  background-size: 200% 200%;
  animation: hatch 1.4s linear infinite;
}
.ghost-line {
  display: block;
  height: 0.7rem;
  width: 72%;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--rule-soft), color-mix(in srgb, var(--cobalt) 8%, transparent), var(--rule-soft));
  background-size: 200% 100%;
  animation: shimmer 1.4s ease-in-out infinite;
}
.ghost-line.is-short { width: 44%; margin-top: 0.4rem; }
.preview.is-ghost:nth-child(2) .ghost-line { animation-delay: 0.15s; }
.preview.is-ghost:nth-child(3) .ghost-line { animation-delay: 0.3s; }

@keyframes hatch { to { background-position: 24px 0; } }
@keyframes shimmer { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }

/* Search suggestions */
.suggest {
  position: absolute;
  z-index: 5;
  top: calc(var(--bar-h, 7rem) + 6px);
  left: 0.5rem;
  right: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  max-height: 16rem;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0.35rem;
  scrollbar-width: thin;
}

.suggest-row {
  display: grid;
  grid-template-columns: 3rem 1fr;
  gap: 0.5rem;
  align-items: center;
  width: 100%;
  text-align: left;
  border: 1px solid var(--rule-soft);
  background: var(--card);
  border-radius: var(--radius);
  padding: 0.3rem;
  transition: border-color var(--ease), background-color var(--ease);
}
.suggest-row.is-active { border-color: var(--cobalt); background: #fbfaf6; box-shadow: inset 3px 0 0 var(--cobalt); }
.suggest-row > span:only-child { grid-column: 1 / -1; padding: 0.15rem 0.35rem; }
.suggest-row .study-art { height: 2.4rem; }

/* Places dock */
.places-dock {
  position: absolute;
  z-index: 3;
  left: 0.5rem;
  right: 0.5rem;
  bottom: max(0.5rem, env(safe-area-inset-bottom));
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem;
}
.places-dock.is-hidden { right: auto; padding: 0.25rem; }
.places-dock .primary, .places-dock .text-button { padding: 0.38rem 0.8rem; }
.app.has-places-dock .map .maplibregl-ctrl-bottom-right { bottom: 4.2rem; }

/* Slim scroll line inside the panel padding. The background stays put while the content scrolls. */
.sheet { scrollbar-width: none; }
.sheet[data-scrollable='true'] {
  background-image: var(--line-thumb), var(--line-track), var(--paper-layers);
  background-size: 3px max(2rem, calc(var(--view, 1) * 100% - 1.5rem)), 1px calc(100% - 1.5rem), var(--paper-sizes);
  background-position: right 5px top calc(0.75rem + var(--scroll, 0) * (100% - 1.5rem - max(2rem, calc(var(--view, 1) * 100% - 1.5rem)))), right 6px top 0.75rem, var(--paper-positions);
  background-repeat: no-repeat, no-repeat, var(--paper-repeat);
}
.rail[data-scrollable='true'] {
  background-image: var(--line-thumb), var(--line-track);
  background-size: 3px max(1.5rem, calc(var(--view, 1) * 100%)), 1px 100%;
  background-position: right 4px top calc(var(--scroll, 0) * 100%), right 5px top 0;
  background-repeat: no-repeat;
}

@media (max-height: 640px) {
  .rail[data-scrollable='true'] {
    background-image: none;
    --fade-top: 18px;
    --fade-end: 28px;
    mask-image: linear-gradient(to bottom, transparent 0, #000 var(--fade-top), #000 calc(100% - var(--fade-end)), transparent 100%);
  }
  .rail[data-at-start='true'] { --fade-top: 0px; }
  .rail[data-at-end='true'] { --fade-end: 0px; }
  .sheet[data-scrollable='true'] {
    background-size: 2px max(1.5rem, calc(var(--view, 1) * 100% - 1.5rem)), 0 0, var(--paper-sizes);
  }
}

/* Phones */
@media (max-width: 700px) {
  :root { font-size: 16px; }
  .bar { padding: 0.5rem 0.55rem; gap: 0.35rem; }
  .mark { font-size: 1.15rem; }
  .search input, .search button { padding: 0.4rem 0.6rem; font-size: 0.85rem; }
  .locate, .chips button, .mediums button, .text-button { padding: 0.32rem 0.5rem; font-size: 0.74rem; }
  .app.has-explorer .map .maplibregl-ctrl-bottom-right { bottom: auto; top: calc(var(--bar-h, 7rem) + 6px); }
  .study-hero { grid-template-columns: 5.2rem 1fr; }
  .study-hero .study-art { height: 3.9rem; }
  .sheet h2 { font-size: 1.5rem; }
  .sheet-actions { flex-direction: column; align-items: stretch; }
  .sheet-actions .primary, .sheet-actions .secondary { width: 100%; }
}

/* Desktop: panels sit in columns over the map. */
@media (min-width: 960px) {
  .bar {
    left: 1rem;
    top: 1rem;
    right: auto;
    width: min(26rem, 32vw);
    padding: 0.8rem 0.9rem;
  }

  .suggest { left: 1rem; right: auto; width: min(26rem, 32vw); }

  .explorer, .explorer[data-snap] {
    left: 1rem;
    right: auto;
    top: calc(var(--bar-h, 9rem) + 0.75rem);
    bottom: 1rem;
    height: auto;
    width: min(26rem, 32vw);
    padding: 0.8rem 0.8rem 0.6rem;
    border-bottom: 1px solid var(--rule);
  }
  .sheet-handle { display: none; }

  .gate { left: 1rem; right: auto; width: min(26rem, 32vw); bottom: auto; top: calc(var(--bar-h, 9rem) + 0.75rem); }

  .sheet {
    top: 1rem;
    right: 1rem;
    bottom: 1rem;
    left: auto;
    width: min(27rem, 34vw);
    max-height: none;
    border-bottom: 1px solid var(--rule);
  }

  .places-dock { left: 1rem; right: auto; width: min(26rem, 32vw); }

  .map .maplibregl-ctrl-bottom-right { bottom: 1rem; right: 1rem; }
  .app:has(.sheet) .map .maplibregl-ctrl-bottom-right { right: calc(min(27rem, 34vw) + 2rem); }
}

/* Spinners adapted from Uiverse Galaxy (MIT): AHMED-MIT nested ring and AbanoubMagdy1 ring.
   https://github.com/uiverse-io/galaxy */
.ink-spin {
  width: 2.2rem;
  height: 2.2rem;
  display: grid;
  border: 3px solid transparent;
  border-radius: 50%;
  border-color: var(--viridian) transparent;
  animation: spin-turn 1s infinite linear;
}
.ink-spin::before,
.ink-spin::after {
  content: "";
  grid-area: 1 / 1;
  margin: 2px;
  border: inherit;
  border-radius: 50%;
}
.ink-spin::before {
  border-color: var(--ink) transparent;
  animation: inherit;
  animation-duration: 0.5s;
  animation-direction: reverse;
}
.ink-spin::after { margin: 7px; }

.voice-spin {
  width: 2rem;
  height: 2rem;
  border: 3px solid var(--cadmium);
  border-top-color: transparent;
  border-bottom-color: transparent;
  border-radius: 50%;
  animation: spin-turn 1.2s infinite linear;
}

.sheet.is-busy .study-art { animation: wash 1.6s ease-in-out infinite; }

@keyframes spin-turn { to { transform: rotate(1turn); } }
@keyframes wash { 50% { opacity: 0.7; } }
@keyframes rise {
  from { transform: translateY(10px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .sheet, .explorer, .gate { animation: none; transition: none; }
  .preview, .locate, .secondary, .text-button, .chips button, .mediums button, .ink-row button,
  .search button, .primary, .use-map, .back-button { transition: none; transform: none !important; }
  .preview.is-ghost .study-art, .ghost-line, .ink-spin, .ink-spin::before, .voice-spin, .sheet.is-busy .study-art, .here-label {
    animation: none;
  }
}

