  background-image: none;

input.old_string:
.plan-note.is-live {
  border-left-color: var(--viridian);
  background: color-mix(in srgb, var(--viridian) 7%, transparent);
}

.ai-mark {
  display: inline-block;
  padding: 0 0.32rem;
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  font-family: var(--mono);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--cobalt);
  vertical-align: 0.08rem;
}

input.new_string:
.plan-note.is-live {
  border-left-color: var(--viridian);
  background: color-mix(in srgb, var(--viridian) 7%, transparent);
  animation: note-in 320ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

input.old_string:
@keyframes rise {
  from { transform: translateY(10px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

input.new_string:
@keyframes rise {
  from { transform: translateY(10px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
@keyframes note-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

input.old_string:
.drop-mark, .drop-card, .look-here {
  animation: none;
}

input.new_string:
.drop-mark, .drop-card, .look-here, .plan-note.is-live {
  animation: none;
}

input.old_string:
--grid:
  linear-gradient(to right, color-mix(in srgb, var(--cobalt) 7%, transparent) 1px, transparent 1px),
  linear-gradient(to bottom, color-mix(in srgb, var(--cobalt) 7%, transparent) 1px, transparent 1px),
  linear-gradient(to right, color-mix(in srgb, var(--cobalt) 13%, transparent) 1px, transparent 1px),
  linear-gradient(to bottom, color-mix(in srgb, var(--cobalt) 13%, transparent) 1px, transparent 1px);
--paper-layers: none;
--paper-sizes: 180px 180px;
--paper-positions: 0 0;
--paper-repeat: repeat;
--line-thumb: linear-gradient(var(--cobalt), var(--cobalt));

background-color: #f7f4ec;
background-image: none;
background-size: var(--paper-sizes);
background-position: var(--paper-positions);
background-repeat: var(--paper-repeat);
border: 1px solid var(--rule);

.chips button.is-on, .mediums button.is-on, .ink-row button.is-on, .chips button[aria-checked='true'], .chips button[aria-pressed='true'] {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}

input.new_string:
.chips button.is-on, .mediums button.is-on, .ink-row button.is-on, .chips button[aria-checked='true'], .chips button[aria-pressed='true'] {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
  animation: chip-set 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

input.old_string:
height: 56dvh;
background-image: var(--paper-layers);
background-size: 16px 16px, 18px 18px, 18px 18px, 90px 90px, 90px 90px;
background-position: top right, 0 0, 0 0, 0 0, 0 0;
background-repeat: no-repeat, repeat, repeat, repeat, repeat;
padding: 0 0.75rem max(0.6rem, env(safe-area-inset-bottom, 0.6rem));

background-image: var(--line-thumb), var(--line-track), var(--paper-layers);
background-size: 3px max(2rem, calc(var(--view, 1) * 100% - 1.5rem)), 1px calc(100% - 1.5rem), var(--paper-sizes);
background-position: right 5px top calc(0.75rem + var(--scroll, 0) * (100% - 1.5rem - max(2rem, calc(var(--view, 1) * 100% - 1.5rem)))), right 6px top 0.75rem, var(--paper-positions);
background-repeat: no-repeat, no-repeat, var(--paper-repeat);

input.new_string:
background-image: var(--line-thumb), var(--line-track);
background-size: 3px max(2rem, calc(var(--view, 1) * 100% - 1.5rem)), 1px calc(100% - 1.5rem);
background-position: right 5px top calc(0.75rem + var(--scroll, 0) * (100% - 1.5rem - max(2rem, calc(var(--view, 1) * 100% - 1.5rem)))), right 6px top 0.75rem;
background-repeat: no-repeat, no-repeat;

input.old_string:
@keyframes note-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

input.new_string:
@keyframes note-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
@keyframes chip-set {
  from { transform: scale(0.94); }
  to { transform: none; }
}
.values.is-fresh { animation: note-in 360ms cubic-bezier(0.2, 0.7, 0.2, 1); }

